using Plumber_Game.Services; using System; using System.Windows.Forms;  namespace Plumber_Game {     public partial class PlumberGame : Form     {         public static int time;         public static bool noClip = false;         public static int amountOfConections = 0;          CharacterDisplay character = new CharacterDisplay();         GameField gameField;          public PlumberGame()         {             InitializeComponent();             gameField = new GameField(tableLayoutPanel1, Levels.CorrectLevelId);         }           private void Form1_Load(object sender, EventArgs e)         {             time = 60;             var levelName = Levels.CorrectlevelList[Levels.CorrectLevelId].Name;             this.Text = $"{TranslationManager.Get("game.title")} | {TranslationManager.Get("game.level")} {levelName}";             noClip = Levels.CorrectlevelList[Levels.CorrectLevelId].IsNoClip;              if (!noClip)             {                 pictureBoxUi1.Visible = false;                 pictureBoxUi2.Visible = false;                 pictureBoxUi3.Visible = false;                 pictureBoxUi4.Visible = false;                 pictureBoxUi5.Visible = false;                 pictureBoxUi6.Visible = false;                 pictureBoxUi7.Visible = false;                 pictureBoxUi8.Visible = false;                 pictureBoxUi9.Visible = false;                 pictureBoxUi10.Visible = false;             }             else             {                 pictureBoxUi1.Visible = true;                 pictureBoxUi2.Visible = true;                 pictureBoxUi3.Visible = true;                 pictureBoxUi4.Visible = true;                 pictureBoxUi5.Visible = true;                 pictureBoxUi6.Visible = true;                 pictureBoxUi7.Visible = true;                 pictureBoxUi8.Visible = true;                 pictureBoxUi9.Visible = true;                 pictureBoxUi10.Visible = true;             }              if (Levels.AvailableLevel == 1 && Levels.CorrectLevelId == 1 && !Levels.CorrectlevelList[Levels.CorrectLevelId].IsCustom)                 MessageBox.Show(TranslationManager.Get("tutorials.level1"), TranslationManager.Get("game.welcome"),                     MessageBoxButtons.OK, MessageBoxIcon.Information);              if (Levels.AvailableLevel == 6 && Levels.CorrectLevelId == 6 && !Levels.CorrectlevelList[Levels.CorrectLevelId].IsCustom)                 MessageBox.Show(TranslationManager.Get("tutorials.level6"), TranslationManager.Get("game.congratulations"),                     MessageBoxButtons.OK, MessageBoxIcon.Information);              if (Levels.AvailableLevel == 11 && Levels.CorrectLevelId == 11 && !Levels.CorrectlevelList[Levels.CorrectLevelId].IsCustom)                 MessageBox.Show(TranslationManager.Get("tutorials.level11"), TranslationManager.Get("game.congratulations"),                     MessageBoxButtons.OK, MessageBoxIcon.Information);              if (Levels.AvailableLevel == 16 && Levels.CorrectLevelId == 16 && !Levels.CorrectlevelList[Levels.CorrectLevelId].IsCustom)             {                 MessageBox.Show(TranslationManager.Get("tutorials.level16"), TranslationManager.Get("game.congratulations"),                     MessageBoxButtons.OK, MessageBoxIcon.Information);             }              timer.Enabled = Levels.CorrectlevelList[Levels.CorrectLevelId].IsOnTime;             this.Enabled = true;             gameField.Update(Levels.CorrectlevelList[Levels.CorrectLevelId], Levels.CorrectLevelId);              character.Show();             character.Attach(this.Location, this.Width);             character.ChangeCharPosition(1);         }          private void pictureBox7_MouseClick(object sender, MouseEventArgs e)         {             PictureBox tile = (PictureBox)sender;               GameField.RotateTile(ref tile);              if (gameField.Check(noClip))             {                 this.Enabled = false;                 timer.Enabled = false;                 character.ChangeCharPosition(2);                 new WinScreen(Levels.CorrectlevelList[Levels.CorrectLevelId]).ShowDialog();                 this.Hide();                 character.Hide();             }         }           private void button1_Click(object sender, EventArgs e)         {             Form1_Load(sender, e);         }           private void timer_Tick(object sender, EventArgs e)         {             var levelName = Levels.CorrectlevelList[Levels.CorrectLevelId].Name;             this.Text = $"{TranslationManager.Get("game.title")} | {TranslationManager.Get("game.level")} {levelName} | {TranslationManager.Get("game.time")}: {--time}s";             if (time == 0)             {                 this.Enabled = false;                 timer.Enabled = false;                 var ans = MessageBox.Show(TranslationManager.Get("game.playAgain"), TranslationManager.Get("game.gameOver"), MessageBoxButtons.YesNo, MessageBoxIcon.Question);                 if (ans == DialogResult.Yes)                     Form1_Load(sender, e);                 else                     this.Close();             }         }          private void PlumberGame_FormClosed(object sender, FormClosedEventArgs e)         {             timer.Enabled = false;             new Menu().Show();             this.Dispose();             character.Dispose();         }          private void PlumberGame_LocationChanged(object sender, EventArgs e)         {             character.Attach(this.Location, this.Width);         }     } } 